files.content:
'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['normalizeBooks']);
assert.strictEqual(typeof api.normalizeBooks, 'function');
const { normalizeBooks } = api;

assert.deepStrictEqual(normalizeBooks([]), []);

const books = [
  { isbn: 'isbn-1', title: 'First', tags: ['z', 'a', 'a', 'M'] },
  { isbn: 'isbn-2', title: '', tags: [] },
  { isbn: 'isbn-3', title: 'Third', tags: ['10', '2'] }
];
const snapshot = JSON.parse(JSON.stringify(books));
const result = normalizeBooks(books);
assert.deepStrictEqual(result, [
  { isbn: 'isbn-1', title: 'First', tags: ['M', 'a', 'a', 'z'] },
  { isbn: 'isbn-2', title: '', tags: [] },
  { isbn: 'isbn-3', title: 'Third', tags: ['10', '2'] }
]);
assert.deepStrictEqual(books, snapshot);
assert.notStrictEqual(result, books);
for (let index = 0; index < books.length; index += 1) {
  assert.notStrictEqual(result[index], books[index]);
  assert.notStrictEqual(result[index].tags, books[index].tags);
}

for (const invalid of [
  null,
  {},
  [null],
  [{}],
  [{ isbn: '', title: 'T', tags: [] }],
  [{ isbn: 1, title: 'T', tags: [] }],
  [{ isbn: 'x', title: 1, tags: [] }],
  [{ isbn: 'x', title: 'T', tags: 'tag' }],
  [{ isbn: 'x', title: 'T', tags: ['ok', 2] }]
]) {
  assert.throws(() => normalizeBooks(invalid), TypeError);
}

assert.throws(
  () => normalizeBooks([
    { isbn: 'same', title: 'One', tags: [] },
    { isbn: 'same', title: 'Two', tags: [] }
  ]),
  RangeError
);

const validationInput = [
  { isbn: 'valid', title: 'Valid', tags: ['b', 'a'] },
  { isbn: '', title: 'Invalid', tags: [] }
];
assert.throws(() => normalizeBooks(validationInput), TypeError);
assert.deepStrictEqual(validationInput[0].tags, ['b', 'a']);

